(()=>{const root=document.querySelector('.genesis'),art=root.querySelector('.genesis-art'),adam=root.querySelector('.art-adam'),creator=root.querySelector('.art-creator'),light=root.querySelector('.contact-light'),palm=root.querySelector('.cyber-palm'),grid=root.querySelector('.portal-grid'),wheel=document.querySelector('#realm-wheel'),range=document.querySelector('#realm-progress'),output=document.querySelector('#realm-value'),play=document.querySelector('#portal-play');let p=0,playing=false,frame=0,last=0,drag=null,realm=-1;const reduced=matchMedia('(prefers-reduced-motion:reduce)').matches;const clamp=v=>Math.max(0,Math.min(1,v));const smooth=(a,b,x)=>{const t=clamp((x-a)/(b-a));return t*t*(3-2*t)};function render(v){p=clamp(v);const contact=smooth(0,.4,p),trans=smooth(.38,.78,p),awaken=smooth(.56,.95,p);adam.style.transform=`translateX(${-45*(1-contact)}px)`;creator.style.transform=`translateX(${45*(1-contact)}px)`;art.style.transform=`translate(-38%,-43%) scale(${1+trans*.8})`;art.style.opacity=1-trans;art.style.filter=`saturate(${.9+trans}) brightness(${.68+contact*.12})`;light.style.opacity=smooth(.18,.4,p)*(1-smooth(.55,.85,p));light.style.transform=`translate(-50%,-50%) scale(${.5+trans*13}) rotate(${p*90}deg)`;palm.style.opacity=awaken;palm.style.transform=`perspective(1000px) translateZ(${(-1+awaken)*200}px) rotateY(${(1-awaken)*65}deg) rotateZ(${(1-awaken)*-16}deg) scale(${.55+awaken*.45})`;grid.style.opacity=awaken*.8;wheel.querySelector('.wheel-ticks').style.transform=`rotate(${p*540}deg)`;wheel.querySelector('.wheel-inner').style.transform=`rotate(${-p*360+30}deg)`;wheel.setAttribute('aria-valuenow',Math.round(p*100));range.value=Math.round(p*100);output.textContent=`${Math.round(p*100)}%`;const next=p<.32?0:p<.65?1:2;if(next!==realm){realm=next;root.querySelectorAll('.realm-stages span').forEach((s,i)=>s.classList.toggle('realm-active',i===realm));root.classList.toggle('awakened',realm===2);document.querySelector('#genesis-title').innerHTML=realm===0?'Before the touch.<br><em>Beyond the ordinary.</em>':realm===1?'A spark between<br><em>two worlds.</em>':'The ancient awakens.<br><em>The future is human.</em>';document.querySelector('#genesis-description').innerHTML=realm===0?'An ancient gesture. A new dimension.<br>Turn the wheel. Bring two worlds together.':realm===1?'Closer, and closer. The moment becomes light.<br>Keep turning to cross into the next realm.':'From painted gesture to luminous detail.<br>Your palm, seen through another dimension.'}}function stop(){playing=false;cancelAnimationFrame(frame);play.textContent='▷';play.setAttribute('aria-label','Play transformation')}function tick(t){if(!playing)return;if(!last)last=t;const dt=Math.min(t-last,50);last=t;render(p+dt/10000);if(p>=1)stop();else frame=requestAnimationFrame(tick)}play.onclick=()=>{if(playing){stop();return}if(p>=.999)render(0);if(reduced){render(1);return}playing=true;last=0;play.textContent='Ⅱ';play.setAttribute('aria-label','Pause transformation');frame=requestAnimationFrame(tick)};document.querySelector('#portal-reset').onclick=()=>{stop();render(0)};range.oninput=()=>{stop();render(Number(range.value)/100)};wheel.onpointerdown=e=>{stop();drag={x:e.clientX,y:e.clientY,p};wheel.setPointerCapture(e.pointerId)};wheel.onpointermove=e=>{if(drag)render(drag.p+(e.clientX-drag.x-(e.clientY-drag.y))/350)};wheel.onpointerup=wheel.onpointercancel=()=>drag=null;wheel.onkeydown=e=>{let value=p;if(['ArrowRight','ArrowUp'].includes(e.key))value+=.05;else if(['ArrowLeft','ArrowDown'].includes(e.key))value-=.05;else if(e.key==='Home')value=0;else if(e.key==='End')value=1;else return;e.preventDefault();stop();render(value)};wheel.addEventListener('wheel',e=>{e.preventDefault();stop();render(p+e.deltaY*.001)},{passive:false});document.addEventListener('visibilitychange',()=>{if(document.hidden)stop()});render(0)})();
